ALTER TABLE bank_statements
  ADD COLUMN source_format ENUM('CSV','XLSX','PDF_TEXT','PDF_OCR') NOT NULL DEFAULT 'CSV' AFTER file_hash,
  ADD COLUMN extraction_confidence DECIMAL(5,2) NULL AFTER source_format,
  ADD COLUMN extraction_warnings JSON NULL AFTER extraction_confidence,
  ADD COLUMN import_profile_id BIGINT UNSIGNED NULL AFTER extraction_warnings;

CREATE TABLE bank_import_profiles(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, concession_id BIGINT UNSIGNED NOT NULL, bank_name VARCHAR(150) NOT NULL, name VARCHAR(160) NOT NULL, format_type ENUM('CSV','XLSX','PDF_TEXT','PDF_OCR') NOT NULL, configuration JSON NOT NULL, validation_status ENUM('DRAFT','VALIDATED','DISABLED') NOT NULL DEFAULT 'DRAFT', created_by BIGINT UNSIGNED NOT NULL, validated_by BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_bank_import_profile(concession_id,name,format_type), CONSTRAINT fk_bank_profile_concession FOREIGN KEY(concession_id) REFERENCES concessions(id), CONSTRAINT fk_bank_profile_creator FOREIGN KEY(created_by) REFERENCES users(id), CONSTRAINT fk_bank_profile_validator FOREIGN KEY(validated_by) REFERENCES users(id)
);
ALTER TABLE bank_statements ADD CONSTRAINT fk_bank_statement_import_profile FOREIGN KEY(import_profile_id) REFERENCES bank_import_profiles(id);

CREATE TABLE bank_extraction_runs(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, statement_id BIGINT UNSIGNED NULL, account_id BIGINT UNSIGNED NOT NULL, source_format ENUM('CSV','XLSX','PDF_TEXT','PDF_OCR') NOT NULL, engine_name VARCHAR(100) NOT NULL, engine_version VARCHAR(80) NULL, status ENUM('STARTED','PREVIEW','FAILED','CONFIRMED') NOT NULL, page_count INT UNSIGNED NULL, extracted_line_count INT UNSIGNED NOT NULL DEFAULT 0, warning_count INT UNSIGNED NOT NULL DEFAULT 0, error_code VARCHAR(80) NULL, error_message VARCHAR(500) NULL, executed_by BIGINT UNSIGNED NOT NULL, executed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_bank_extraction_account(account_id,executed_at), CONSTRAINT fk_bank_extraction_statement FOREIGN KEY(statement_id) REFERENCES bank_statements(id), CONSTRAINT fk_bank_extraction_account FOREIGN KEY(account_id) REFERENCES treasury_accounts(id), CONSTRAINT fk_bank_extraction_actor FOREIGN KEY(executed_by) REFERENCES users(id)
);

CREATE TABLE bank_reconciliation_groups(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, agency_id BIGINT UNSIGNED NULL, concession_id BIGINT UNSIGNED NOT NULL, currency_code CHAR(3) NOT NULL, status ENUM('DRAFT','VALIDATED','CANCELLED') NOT NULL DEFAULT 'DRAFT', match_level ENUM('CERTAIN','PROBABLE','AMBIGUOUS','MANUAL') NOT NULL, total_bank_amount DECIMAL(18,2) NOT NULL DEFAULT 0, total_erp_amount DECIMAL(18,2) NOT NULL DEFAULT 0, difference_amount DECIMAL(18,2) NOT NULL DEFAULT 0, client_request_id CHAR(36) NOT NULL, payload_hash CHAR(64) NOT NULL, prepared_by BIGINT UNSIGNED NOT NULL, prepared_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, validated_by BIGINT UNSIGNED NULL, validated_at DATETIME NULL, cancelled_by BIGINT UNSIGNED NULL, cancelled_at DATETIME NULL, cancellation_reason VARCHAR(1000) NULL, UNIQUE KEY uq_bank_group_request(prepared_by,client_request_id), KEY idx_bank_group_scope(concession_id,agency_id,status,prepared_at), CONSTRAINT fk_bank_group_agency FOREIGN KEY(agency_id) REFERENCES agencies(id), CONSTRAINT fk_bank_group_concession FOREIGN KEY(concession_id) REFERENCES concessions(id), CONSTRAINT fk_bank_group_preparer FOREIGN KEY(prepared_by) REFERENCES users(id), CONSTRAINT fk_bank_group_validator FOREIGN KEY(validated_by) REFERENCES users(id), CONSTRAINT fk_bank_group_canceller FOREIGN KEY(cancelled_by) REFERENCES users(id)
);
CREATE TABLE bank_reconciliation_allocations(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, group_id BIGINT UNSIGNED NOT NULL, statement_line_id BIGINT UNSIGNED NOT NULL, treasury_movement_id BIGINT UNSIGNED NOT NULL, allocated_amount DECIMAL(18,2) NOT NULL, status ENUM('ACTIVE','RELEASED') NOT NULL DEFAULT 'ACTIVE', active_group_id BIGINT UNSIGNED GENERATED ALWAYS AS(CASE WHEN status='ACTIVE' THEN group_id ELSE NULL END) STORED, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, released_at DATETIME NULL, UNIQUE KEY uq_bank_allocation_group(group_id,statement_line_id,treasury_movement_id), KEY idx_bank_allocation_line(statement_line_id,status), KEY idx_bank_allocation_movement(treasury_movement_id,status), CONSTRAINT chk_bank_allocation_positive CHECK(allocated_amount>0), CONSTRAINT fk_bank_allocation_group FOREIGN KEY(group_id) REFERENCES bank_reconciliation_groups(id), CONSTRAINT fk_bank_allocation_line FOREIGN KEY(statement_line_id) REFERENCES bank_statement_lines(id), CONSTRAINT fk_bank_allocation_movement FOREIGN KEY(treasury_movement_id) REFERENCES treasury_movements(id)
);
CREATE TABLE bank_reconciliation_discrepancies(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, statement_line_id BIGINT UNSIGNED NOT NULL, category ENUM('BANK_FEE','COMMISSION','DATE_DIFFERENCE','AMOUNT_DIFFERENCE','MISSING_ERP_OPERATION','OUTSTANDING_RECEIPT','OUTSTANDING_CHEQUE','TRANSFER_IN_TRANSIT','UNKNOWN','OTHER') NOT NULL, status ENUM('OPEN','JUSTIFIED','RESOLVED','CANCELLED') NOT NULL DEFAULT 'OPEN', amount DECIMAL(18,2) NULL, justification VARCHAR(1000) NULL, accounting_entry_id BIGINT UNSIGNED NULL, created_by BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, resolved_by BIGINT UNSIGNED NULL, resolved_at DATETIME NULL, KEY idx_bank_discrepancy_status(status,created_at), CONSTRAINT fk_bank_discrepancy_line FOREIGN KEY(statement_line_id) REFERENCES bank_statement_lines(id), CONSTRAINT fk_bank_discrepancy_entry FOREIGN KEY(accounting_entry_id) REFERENCES accounting_entries(id), CONSTRAINT fk_bank_discrepancy_creator FOREIGN KEY(created_by) REFERENCES users(id), CONSTRAINT fk_bank_discrepancy_resolver FOREIGN KEY(resolved_by) REFERENCES users(id)
);

INSERT INTO permissions(module,action,code,name,label,group_name,description,is_active) VALUES
('bank_reconciliation','manage','treasury.bank_account.manage','Gérer les comptes bancaires','Gérer les comptes bancaires','Comptabilité & Trésorerie','Créer, modifier, activer et désactiver les comptes Treasury bancaires',TRUE),
('bank_reconciliation','view','treasury.reconciliation.dashboard','Voir le pilotage bancaire','Voir le pilotage bancaire','Comptabilité & Trésorerie','Consulter les indicateurs de rapprochement',TRUE),
('bank_reconciliation','manage','treasury.reconciliation.profile.manage','Gérer les profils d’import','Gérer les profils d’import','Comptabilité & Trésorerie','Configurer les formats bancaires validés',TRUE),
('bank_reconciliation','manage','treasury.reconciliation.discrepancy.manage','Gérer les écarts bancaires','Gérer les écarts bancaires','Comptabilité & Trésorerie','Qualifier et résoudre les écarts sans correction silencieuse',TRUE),
('bank_reconciliation','view','treasury.reconciliation.history','Consulter l’historique bancaire','Consulter l’historique bancaire','Comptabilité & Trésorerie','Consulter les extractions et rapprochements',TRUE)
ON DUPLICATE KEY UPDATE name=VALUES(name),label=VALUES(label),group_name=VALUES(group_name),description=VALUES(description),is_active=TRUE;
INSERT INTO role_permissions(role_id,permission_id,scope) SELECT r.id,p.id,'GLOBAL' FROM roles r CROSS JOIN permissions p WHERE r.code='SUPER_ADMIN' AND r.is_system=TRUE AND r.is_active=TRUE AND p.code LIKE 'treasury.reconciliation.%' ON DUPLICATE KEY UPDATE scope=VALUES(scope);
